def resolve_model_name(
    explicit: str | None = None,
    *,
    configured: str | None = None,
) -> str | None:
    """[CFG-5] model precedence: --model, LLM_MODEL, config, llm default.

    CLI beats env beats config -- [CFG-5]'s assembly order puts environment
    variables ABOVE the config file, so `LLM_MODEL` overrides
    `analyze.model` whenever --model is omitted.

    Returns ``None`` to mean "let ``llm`` use its configured default" so the
    lazy-import boundary stays in ``default_adapter``.
    """

    import os

    if explicit is not None and explicit.strip():
        return explicit.strip()
    env = os.environ.get("LLM_MODEL", "").strip()
    if env:
        return env
    if configured is not None and configured.strip():
        return configured.strip()
    return None

def _cmd_check(args: argparse.Namespace) -> int:
    settings = _resolve_settings(args)
    profile = _profile_from(args, settings)
    pipeline = build_check_report(args.repo_root, profile, settings)

    for warning in pipeline.warnings:
        print(f"warning: {warning}", file=sys.stderr)

    # [CFG-5]: config-set check.format and check.output apply when
    # the CLI flag is omitted; a parsed-but-unconsulted key is dead schema.
    fmt = args.format or settings.check.format or "text"
    output = args.output
    if output is None and settings.check.output is not None:
        output = Path(settings.check.output)

    shown = pipeline.suppressed if args.show_suppressions else None
    rendered = (
        render_json(pipeline.report, shown)
        if fmt == "json"
        else render_text(pipeline.report, shown)
    )

    if output is not None:
        # Known fable defect fixed at port time: an unwritable --output path
        # must be exit 2 with a one-line error, never a traceback/exit 1.
        try:
            output.write_text(rendered, encoding="utf-8")
        except OSError as exc:
            return _error(f"cannot write --output {output}: {exc}")
    else:
        sys.stdout.write(rendered)

    fail_on = set(settings.diagnostics.fail_on)
    warnings_as_errors = args.warnings_as_errors
    if warnings_as_errors is None:
        warnings_as_errors = bool(settings.check.warnings_as_errors)
    if warnings_as_errors:
        fail_on.add("warning")
    if any(issue.severity in fail_on for issue in pipeline.report.issues):
        return 1
    return 0

def _profile_from(
    args: argparse.Namespace, settings: BackstitchSettings
) -> ProfileConfig:
    """[CFG-5] precedence: CLI flags > config values > built-in profile."""

    # An explicit --profile beats config; config beats the built-in default.
    name = args.profile or settings.profile or "backstitch-style-v1"
    profile = _configured_profile(settings, name=name)
    cli_overrides: dict[str, tuple[str, ...]] = {}
    if args.spec_roots is not None:
        cli_overrides["spec_roots"] = tuple(args.spec_roots)
    if args.plan_roots is not None:
        cli_overrides["plan_roots"] = tuple(args.plan_roots)
    if args.code_roots is not None:
        cli_overrides["code_roots"] = tuple(
            expand_root_value(value) for value in args.code_roots
        )
    if args.test_roots is not None:
        cli_overrides["test_roots"] = tuple(
            expand_root_value(value) for value in args.test_roots
        )
    if cli_overrides:
        profile = profile.with_overrides(**cli_overrides)
    _validate_test_root_containment(args.repo_root.resolve(), profile)
    return profile

def _resolve_settings(args: argparse.Namespace) -> BackstitchSettings:
    """[CFG-5]: config discovery anchored at the resolved repo root."""

    if args.no_config and args.config is not None:
        msg = "--config and --no-config are mutually exclusive"
        raise ConfigLoadError(msg)
    if args.no_config:
        return load_settings(args.repo_root.resolve(), use_repo_config=False)
    return load_settings(args.repo_root.resolve(), explicit=args.config)

"""Diagnostic registry, aliases, and ordered reporting policy.

Spec: docs/specs/02-backstitch-core.md [SC-6], [SC-11], [SC-15]
Spec: docs/specs/03-backstitch-configuration.md [CFG-5], [CFG-6], [CFG-8]
Spec: docs/specs/04-backstitch-traceability-exclusions.md [EXC-4], [EXC-8]
Spec: docs/specs/05-backstitch-invariants.md [INV-4], [INV-8]
"""

from __future__ import annotations

import dataclasses
import functools
import importlib.resources
import tomllib
from dataclasses import dataclass
from typing import Any, Literal

Severity = Literal["error", "warning", "info"]
DiagnosticLevel = Literal["error", "warning", "info", "off"]
DiagnosticStatus = Literal["implemented", "reserved", "deprecated", "redirected"]

SEVERITIES: frozenset[str] = frozenset({"error", "warning", "info"})
DIAGNOSTIC_LEVELS: frozenset[str] = frozenset({"error", "warning", "info", "off"})
DIAGNOSTIC_STATUSES: frozenset[str] = frozenset(
    {"implemented", "reserved", "deprecated", "redirected"}
)
DEFAULTS_RESOURCE = "defaults.toml"
OFF_AUDIT_REASON = "diagnostic level off"
SEMANTIC_DIAGNOSTIC_PREFIX = "SEMANTIC_"


class DiagnosticConfigError(ValueError):
    """The packaged diagnostic registry or configured policy is invalid."""


@dataclass(frozen=True, slots=True)
class DiagnosticDefinition:
    code: str
    short_code: str
    status: DiagnosticStatus
    summary: str
    contexts: tuple[str, ...] = ()
    replacement: str | None = None


@dataclass(frozen=True, slots=True)
class DiagnosticRegistry:
    definitions: dict[str, DiagnosticDefinition]
    short_to_code: dict[str, str]

    def require(self, code: str) -> DiagnosticDefinition:
        try:
            return self.definitions[code]
        except KeyError:
            raise DiagnosticConfigError(f"unknown diagnostic code: {code}") from None

    def canonical_code(self, code_or_short: str) -> str:
        if code_or_short in self.definitions:
            code = code_or_short
        elif code_or_short in self.short_to_code:
            code = self.short_to_code[code_or_short]
        else:
            raise DiagnosticConfigError(f"unknown diagnostic code: {code_or_short}")

        chain: list[str] = []
        seen: set[str] = set()
        while True:
            if code in seen:
                cycle = " -> ".join((*chain, code))
                raise DiagnosticConfigError(
                    f"diagnostic replacement cycle detected: {cycle}"
                )
            seen.add(code)
            chain.append(code)

            definition = self.require(code)
            if definition.status == "implemented":
                return code
            if definition.status not in {"deprecated", "redirected"}:
                raise DiagnosticConfigError(
                    f"diagnostic {code_or_short} resolves to {code} with status"
                    f" {definition.status}; expected implemented"
                )
            if definition.replacement is None:
                raise DiagnosticConfigError(
                    f"diagnostic {code} has status {definition.status} but no replacement"
                )
            if definition.replacement not in self.definitions:
                raise DiagnosticConfigError(
                    f"diagnostic {code} replacement is not a known diagnostic:"
                    f" {definition.replacement}"
                )
            code = definition.replacement

    def implemented_codes(self) -> frozenset[str]:
        return frozenset(
            code
            for code, definition in self.definitions.items()
            if definition.status == "implemented"
        )


@dataclass(frozen=True, slots=True)
class DiagnosticLevelRule:
    selectors: tuple[str, ...]
    level: DiagnosticLevel


@dataclass(frozen=True, slots=True)
class DiagnosticsSettings:
    default_level: DiagnosticLevel = "warning"
    levels: tuple[DiagnosticLevelRule, ...] = ()
    fail_on: tuple[Severity, ...] = ("error",)
    suppressible_levels: tuple[Severity, ...] = ("warning", "info")


